  // resolve in the coordinates of the transformed (view-side) document. Without a live
  // binding (headless usage, or the pre-setup/stale-binding window) the positions
  // resolve directly against the Y render. `ystate` is passed through explicitly
  // because this can run mid-dispatch with an overlaid sync state (see the plugin's
  // `apply`).
  /**
   * @type {Array<import('prosemirror-model').ResolvedPos | null>}
   */
  let positions
  try {
    positions = mapRelativePositionsToResolvedPositions(state, rposs, ystate)
  } catch (err) {
    // should not happen - drop the remote cursors for this render rather than tearing
    // down the dispatch; decorations recompute on the next state change
    console.warn('y-prosemirror cursor-plugin: position mapping failed, skipping remote cursors', err)
    return DecorationSet.empty
  }
  /**
   * @type {Decoration[]}
   */
  const decorations = []
  entries.forEach(({ clientId, user }, i) => {
    const resolvedAnchor = positions[i * 2]
    const resolvedHead = positions[i * 2 + 1]
    if (resolvedAnchor !== null && resolvedHead !== null) {
      const anchor = math.min(resolvedAnchor.pos, maxsize)
      const head = math.min(resolvedHead.pos, maxsize)
      decorations.push(
        Decoration.widget(head, () => createCursor(user, clientId), {
          key: clientId + '',
          side: 10
        })
      )
      decorations.push(
        Decoration.inline(math.min(anchor, head), math.max(anchor, head), createSelection(user, clientId), {
          inclusiveEnd: true,
          inclusiveStart: false
        })
      )
    }
  })
  return DecorationSet.create(state.doc, decorations)
}

/**
 * @callback ResolveLocalCursorStateCallback
 * @param {object} ctx - The context object
 * @param {import('prosemirror-view').EditorView} ctx.view - The editor view
 * @param {{anchor: Y.RelativePosition, head: Y.RelativePosition} | null} ctx.prevState - The previous local cursor state currently published in awareness for this client (decoded to Y.RelativePosition), or null if not set
 * @param {{anchor: Y.RelativePosition, head: Y.RelativePosition} | null} ctx.nextState - The candidate next cursor state, freshly derived from the editor's current selection (not yet published to awareness), or null if no Y type is bound or the selection could not be anchored in the Y document
 * @param {boolean} ctx.isOwnState - Whether `prevState` resolves inside this editor binding's bound type (i.e. this binding is the source of truth for the published cursor state)
 * @param {'update' | 'focus' | 'blur'} ctx.reason - What triggered this invocation: 'update' (PM view.update tick), 'focus' (focusin on view.dom; only fires when no `setSelection` transaction is pending — see `selectionUpdateIsPending` in cursor-plugin.js), or 'blur' (focusout on view.dom)
 * @returns {{anchor: Y.RelativePosition, head: Y.RelativePosition} | null} The next local cursor state to publish under `cursorStateField` in awareness, or null to clear it
 */

/**
 * A prosemirror plugin that listens to awareness information on Yjs.
 * This requires that a `prosemirrorPlugin` is also bound to the prosemirror.
 *
 * @public
 * @param {import('@y/protocols/awareness').Awareness} awareness
 * @param {object} opts
 * @param {AwarenessFilter} [opts.awarenessStateFilter] A function that filters the awareness states to be rendered
 * @param {(user: User, clientId: number) => HTMLElement} [opts.cursorBuilder] A function that creates a cursor element
 * @param {(user: User, clientId: number) => import('prosemirror-view').DecorationAttrs} [opts.selectionBuilder] A function that creates a selection decoration
 * @param {ResolveLocalCursorStateCallback} [opts.resolveLocalCursorState] A policy that decides which cursor state to publish to awareness given the previously-published state, the state derived from the current selection, and what triggered the update
 * @param {string} [opts.cursorStateField = 'cursor'] By default all editor bindings use the awareness 'cursor' field to propagate cursor information, this allows you to use a different field name
 * @return {Plugin<DecorationSet>}
 */
export const yCursorPlugin = (
  awareness,
  {
    awarenessStateFilter = (currentClientId, userClientId) => currentClientId !== userClientId,
    cursorBuilder = defaultCursorBuilder,
    selectionBuilder = defaultSelectionBuilder,
    cursorStateField = 'cursor',
    resolveLocalCursorState = (ctx) => {
      if (ctx.view.hasFocus()) {
        return ctx.nextState
      }
      // clear the published cursor state if this binding owns it,
      // otherwise leave the previously-published state in place
      return ctx.isOwnState ? null : ctx.prevState
    }
  } = {}
) =>
  new Plugin({
    key: yCursorPluginKey,
    state: {
      init (_, state) {
        return createDecorations(
          state,
          awareness,
          awarenessStateFilter,
          cursorBuilder,
          selectionBuilder,
          cursorStateField,
          undefined
        )
      },
      apply (tr, prevState, oldState, newState) {
        const ySyncMeta = $syncPluginStateUpdate.nullable.expect(tr.getMeta(ySyncPluginKey) || null)
        const ySyncTransaction = tr.getMeta('y-sync-transaction')
        const yCursorMeta = tr.getMeta(yCursorPluginKey)

        if (ySyncMeta || ySyncTransaction || yCursorMeta?.awarenessUpdated) {
          // PM fills `newState` plugin fields in field order during apply, so
          // `ySyncPluginKey.getState(newState)` may return null if this plugin
          // runs before the sync plugin (which can happen when the host
          // editor — e.g., Tiptap/BlockNote — orders plugins by name or
          // priority). Read the sync state from `oldState` (fully populated)
          // and overlay the in-flight update from this transaction's meta, if
          // any, so we still see the new ytype the moment configureYProsemirror
          // is dispatched.
          const baseSync = ySyncPluginKey.getState(oldState) || ySyncPluginKey.getState(newState)
          const syncState = ySyncMeta ? Object.assign({}, baseSync, ySyncMeta) : baseSync
          return createDecorations(
            newState,
            awareness,
            awarenessStateFilter,
            cursorBuilder,
            selectionBuilder,
            cursorStateField,
            syncState
          )
        }
        // remap decorations
        return prevState.map(tr.mapping, tr.doc)
      }
    },
    props: {
      decorations: (state) => yCursorPluginKey.getState(state)
    },
    view: (view) => {
      const awarenessListener = () => {
        if (view.isDestroyed) {
          return
        }
        view.dispatch(view.state.tr.setMeta(yCursorPluginKey, { awarenessUpdated: true }))
      }

      /**
       * @param {'update' | 'focus' | 'blur'} reason
       */
      const updateCursorInfo = (reason) => {
        if (view.isDestroyed) {
          return
        }
        const ystate = ySyncPluginKey.getState(view.state)
        const rawCursor = (awareness.getLocalState() || {})[cursorStateField]
        /**
         * @type {{anchor: Y.RelativePosition, head: Y.RelativePosition} | null}
         */
        const prevState = rawCursor != null
          ? {
              anchor: Y.createRelativePositionFromJSON(rawCursor.anchor),
              head: Y.createRelativePositionFromJSON(rawCursor.head)
            }
          : null

        // Belt-and-braces around the PM->Y position encoding. positions.js
        // already falls back to a doc-root relative position on traversal
        // failure, but anything else throwing here (DOM-change-time selection
        // resolution, renderer internals) would bubble up through dispatch and
        // tear the editor down on every keystroke - just skip the awareness
        // update in that case.
        /** @type {{anchor: Y.RelativePosition, head: Y.RelativePosition} | null} */
        let nextState = null
        if (ystate?.ytype) {
          try {
            const sel = view.state.selection
            // map the selection through the binding transformer (view→data) so the
            // published positions anchor where the content actually lives in Y
            const mapped = resolvedPositionsToRelativePositions(view, [sel.$anchor, sel.$head])
            // An unresolvable endpoint leaves nextState null - the policy then clears
            // the published cursor. Never publish a half-mapped pair (it could invert
            // the selection).
            if (mapped[0] != null && mapped[1] != null) {
              nextState = { anchor: mapped[0], head: mapped[1] }
            }
          } catch (err) {
            console.warn('y-prosemirror cursor-plugin: failed to encode selection, skipping awareness update', err)
            return
          }
        }
        const resolvedState = resolveLocalCursorState({
          view,
          prevState,
          nextState,
          reason,
          get isOwnState () {
            // a pure containment check ("does the published rpos resolve inside the
            // bound type") - Y-side resolution suffices, no transformer pass needed
            return prevState != null && ystate?.ytype != null && Y.createDeltaPositionFromRelativePosition(
              ystate.ytype,
              prevState.anchor,
              { renderer: ystate.renderer ?? null }
            ) != null
          }
        })

        // compute whether the published cursor state has changed
        const cursorChanged = (prevState == null) !== (resolvedState == null) || (
          prevState != null && resolvedState != null && (
            !Y.compareRelativePositions(prevState.anchor, resolvedState.anchor) ||
            !Y.compareRelativePositions(prevState.head, resolvedState.head)
          )
        )

        if (cursorChanged) {
          awareness.setLocalStateField(cursorStateField, resolvedState)
        }
      }

      const onFocusIn = () => {
        if (view.isDestroyed) return
        // This fixes an issue where focusin is called before the selection is updated
        // This allows us to bail out if the selection will change immediately after focusin
        // This allows us to skip a flicker of setting the cursor, just to change it to the correct position
        /** @type {Selection | null} */
        const sel = (/** @type {any} */ (view.root)).getSelection()
        if (sel && sel.rangeCount > 0 && sel.anchorNode) {
          try {
            if (view.posAtDOM(sel.anchorNode, sel.anchorOffset, -1) !== view.state.selection.anchor) {
              return
            }
          } catch { /* posAtDOM failed; re-evaluate the cursor */ }
        }
        updateCursorInfo('focus')
      }
      const onFocusOut = () => updateCursorInfo('blur')

      awareness.on('change', awarenessListener)
      view.dom.addEventListener('focusin', onFocusIn)
      view.dom.addEventListener('focusout', onFocusOut)

      return {
        update: () => updateCursorInfo('update'),
        destroy: () => {
          view.dom.removeEventListener('focusin', onFocusIn)
          view.dom.removeEventListener('focusout', onFocusOut)
          awareness.off('change', awarenessListener)
        }
      }
    }
  })

import { isNumeric } from '../common';

interface GetCursorPositionProps {
  phoneBeforeInput: string;
  phoneAfterInput: string;
  phoneAfterFormatted: string;
  cursorPositionAfterInput: number;
  leftOffset?: number;
  deletion?: 'forward' | 'backward' | undefined;
}

export const getCursorPosition = ({
  phoneBeforeInput,
  phoneAfterInput,
  phoneAfterFormatted,
  cursorPositionAfterInput,
  leftOffset = 0,
  deletion,
}: GetCursorPositionProps) => {
  if (cursorPositionAfterInput < leftOffset) {
    return leftOffset;
  }

  if (!phoneBeforeInput) {
    return phoneAfterFormatted.length;
  }

  let afterInputPointIndex: number | null = null;

  // iterate from right to left and get first digit char
  for (let index = cursorPositionAfterInput - 1; index >= 0; index -= 1) {
    if (isNumeric(phoneAfterInput[index])) {
      afterInputPointIndex = index;
      break;
    }
  }

  if (afterInputPointIndex === null) {
    for (let index = 0; index < phoneAfterInput.length; index += 1) {
      if (isNumeric(phoneAfterFormatted[index])) {
        return index;
      }
    }

    return phoneAfterInput.length;
  }

  // find "digit index" of new char (only digits count)
  let digitIndex = 0;
  for (let index = 0; index < afterInputPointIndex; index += 1) {
    if (isNumeric(phoneAfterInput[index])) {
      digitIndex += 1;
    }
  }

  // find cursor position by going over digits until we get digitIndex
  let cursorPosition = 0;
  let digitsCounter = 0;
  for (let index = 0; index < phoneAfterFormatted.length; index += 1) {
    cursorPosition += 1;

    if (isNumeric(phoneAfterFormatted[index])) {
      digitsCounter += 1;
    }

    if (digitsCounter >= digitIndex + 1) {
      break;
    }
  }

  // set cursor before next digit (jump over mask chars on the right side)
  if (deletion !== 'backward') {
    while (
      !isNumeric(phoneAfterFormatted[cursorPosition]) &&
      cursorPosition < phoneAfterFormatted.length
    ) {
      cursorPosition += 1;
    }
  }

  return cursorPosition;
};

import { getCursorPosition } from '../getCursorPosition';

describe('getCursorPosition', () => {
  test('should handle empty value', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '',
        phoneAfterInput: '1',
        cursorPositionAfterInput: '1'.length,
        phoneAfterFormatted: '+1 ',
      }),
    ).toBe(3);
  });

  test('should handle set in the end', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '+380 (9',
        phoneAfterInput: '+380 (97',
        cursorPositionAfterInput: '+380 (97'.length,
        phoneAfterFormatted: '+380 (97) ',
      }),
    ).toBe('+380 (97) '.length);
  });

  test('should handle set in the middle', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-',
        phoneAfterInput: '+1 (111) 9111-',
        cursorPositionAfterInput: '+1 (111) 9'.length,
        phoneAfterFormatted: '+1 (111) 911-1',
      }),
    ).toBe('+1 (111) 9'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-1111',
        phoneAfterInput: '+1 (119991) 111-1111',
        cursorPositionAfterInput: '+1 (11999'.length,
        phoneAfterFormatted: '+1 (119) 991-1111',
      }),
    ).toBe('+1 (119) 99'.length);
  });

  test('should handle removal', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-1111',
        phoneAfterInput: '+1 (11) 111-1111',
        cursorPositionAfterInput: '+1 (11'.length,
        phoneAfterFormatted: '+1 (111) 111-111',
      }),
    ).toBe('+1 (11'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (234) 567-8901',
        phoneAfterInput: '+1 (24) 567-8901',
        cursorPositionAfterInput: '+1 (2'.length,
        phoneAfterFormatted: '+1 (245) 678-901',
      }),
    ).toBe('+1 (2'.length);

    // mimic forceDialCode behavior
    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (234) 567-8901',
        phoneAfterInput: '',
        cursorPositionAfterInput: 0,
        phoneAfterFormatted: '+1',
        leftOffset: '+1'.length,
      }),
    ).toBe('+1'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+380',
        phoneAfterInput: '+38',
        cursorPositionAfterInput: '+38'.length,
        phoneAfterFormatted: '+380',
        leftOffset: '+380'.length,
      }),
    ).toBe('+380'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+48',
        phoneAfterInput: '+380',
        cursorPositionAfterInput: '+380'.length,
        phoneAfterFormatted: '+380 ',
        leftOffset: '+380 '.length,
      }),
    ).toBe('+380 '.length);
  });

  test('should handle change in full phone', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-1111',
        phoneAfterInput: '+1 (9111) 111-1111',
        cursorPositionAfterInput: '+1 (9'.length,
        phoneAfterFormatted: '+1 (911) 111-1111',
      }),
    ).toBe('+1 (9'.length);
  });

  test('should handle selection removal', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-',
        phoneAfterInput: '1',
        cursorPositionAfterInput: '1'.length,
        phoneAfterFormatted: '+1 ',
      }),
    ).toBe('+1 '.length);
  });

  test('should handle input before mask char', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-111',
        phoneAfterInput: '+1 9(111) 111-111',
        cursorPositionAfterInput: '+1 9'.length,
        phoneAfterFormatted: '+1 (911) 111-1111',
      }),
    ).toBe('+1 (9'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-111',
        phoneAfterInput: '+19 (111) 111-111',
        cursorPositionAfterInput: '+19'.length,
        phoneAfterFormatted: '+1 (911) 111-1111',
      }),
    ).toBe('+1 (9'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-111',
        phoneAfterInput: '+91 (111) 111-111',
        cursorPositionAfterInput: '+9'.length,
        phoneAfterFormatted: '+9 (111) 111-1111',
      }),
    ).toBe('+9 ('.length);
  });

  test('should handle prefix removal', () => {
    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 (111) 111-111',
        phoneAfterInput: '1 (111) 111-111',
        cursorPositionAfterInput: 0,
        phoneAfterFormatted: '+1 (111) 111-1111',
        deletion: 'backward',
      }),
    ).toBe('+'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+380',
        phoneAfterInput: '380',
        cursorPositionAfterInput: 0,
        phoneAfterFormatted: '+380 ',
        deletion: 'backward',
      }),
    ).toBe('+'.length);

    expect(
      getCursorPosition({
        phoneBeforeInput: '+1 ',
        phoneAfterInput: ' ',
        cursorPositionAfterInput: 0,
        phoneAfterFormatted: '+',
        deletion: 'forward',
      }),
    ).toBe('+'.length);
  });
});

import ICursorHighlight from './i-cursor-highlight.js';

let nextHighlightNumber = 0;

// Only constructed when isSupported(); methods assume the Highlight API
// globals exist.
export default class CursorHighlight implements ICursorHighlight {
  public static readonly NAME_PREFIX = 'ql-cursor-highlight';
  // Single source of truth for the fade lives in the stylesheet, which also
  // uses it for the embed overlay opacity; the fallback covers setups that
  // load the core bundle without the stylesheet.
  public static readonly SELECTION_FADE = 'var(--ql-cursor-selection-fade, 0.3)';

  private static _hasWarnedUnsupported = false;

  public static isSupported(): boolean {
    return typeof Highlight !== 'undefined' &&
      typeof CSS !== 'undefined' &&
      !!CSS.highlights;
  }

  public static warnIfUnsupported(): void {
    if (CursorHighlight.isSupported() || CursorHighlight._hasWarnedUnsupported) return;
    CursorHighlight._hasWarnedUnsupported = true;
    // eslint-disable-next-line no-console
    console.warn(
      'quill-cursors: This browser does not support the CSS Custom Highlight API. ' +
      'Cursor carets and flags will work, but selection ranges will not be shown. ' +
      'See https://github.com/reedsy/quill-cursors#browser-support',
    );
  }

  // The color is interpolated into a stylesheet, where (unlike an inline
  // style property assignment) a malicious string could escape the
  // declaration and inject arbitrary document-level CSS. Validating it as a
  // standalone color value prevents any breakout, while still allowing
  // custom properties like var(--user-color).
  private static _safeColor(color: string): string {
    return CSS.supports('background-color', color) ? color : 'transparent';
  }

  // Another copy of this module on the same page (e.g. duplicated bundles)
  // shares the page-global registry but not this counter, so skip taken numbers.
  private static _nextNumber(): number {
    let number = nextHighlightNumber++;
    while (CSS.highlights.has(`${CursorHighlight.NAME_PREFIX}-${number}`)) {
      number = nextHighlightNumber++;
    }
    return number;
  }

  public readonly name: string;

  private readonly _color: string;
  private readonly _priority: number;
  private _highlight: Highlight | null = null;
  private _sheet: CSSStyleSheet | null = null;
  private _root: Document | ShadowRoot | null = null;

  public constructor(color: string) {
    this._color = CursorHighlight._safeColor(color);
    this._priority = CursorHighlight._nextNumber();
    this.name = `${CursorHighlight.NAME_PREFIX}-${this._priority}`;
    // Register eagerly: this reserves the name in the page-global registry,
    // so another module copy probing _nextNumber cannot take the same one.
    this._register();
  }

  // The root is passed per call: the cursor element has no root until it is
  // attached to the DOM after build().
  public setRange(range: Range | null, root: Node): void {
    const highlight = this._attach(root);
    this.clear();
    if (range) {
      highlight.add(range);
    }
  }

  public clear(): void {
    if (!this._highlight) return;
    this._highlight.clear();
  }

  // Hiding disables the stylesheet instead of dropping the ranges, so
  // becoming visible again does not need a selection update.
  public setVisible(visible: boolean): void {
    if (!this._sheet) return;
    this._sheet.disabled = !visible;
  }

  public detach(): void {
    CSS.highlights.delete(this.name);
    this._highlight = null;
    if (this._sheet) {
      this._sheet.disabled = false;
    }
    this._removeSheet();
  }

  private _register(): Highlight {
    const highlight = new Highlight();
    // Later-created cursors paint on top when selections overlap. Priority
    // is fixed at creation: it cannot track document position, which
    // changes with every edit.
    highlight.priority = this._priority;
    CSS.highlights.set(this.name, highlight);
    this._highlight = highlight;
    return highlight;
  }

  private _attach(root: Node): Highlight {
    // Re-attach after detach()
    const highlight = this._highlight || this._register();
    this._adoptSheetInto(this._styleRoot(root));
    return highlight;
  }

  private _adoptSheetInto(root: Document | ShadowRoot | null): void {
    if (!root || root === this._root) return;

    // The editor has moved to a different document or shadow root
    this._removeSheet();

    if (!this._sheet) {
      this._sheet = this._buildSheet();
    }

    root.adoptedStyleSheets.push(this._sheet);
    this._root = root;
  }

  private _removeSheet(): void {
    if (!this._root) return;

    const sheets = this._root.adoptedStyleSheets;
    // A root is only recorded once its sheet has been adopted.
    const index = sheets.indexOf(this._sheet!);
    if (index >= 0) {
      sheets.splice(index, 1);
    }
    this._root = null;
  }

  private _buildSheet(): CSSStyleSheet {
    const sheet = new CSSStyleSheet();
    const fade = `calc(${CursorHighlight.SELECTION_FADE} * 100%)`;
    const background = `color-mix(in srgb, ${this._color} ${fade}, transparent)`;
    sheet.replaceSync(`::highlight(${this.name}) { background-color: ${background}; }`);
    return sheet;
  }

  // instanceof is realm-sensitive by design: constructable stylesheets cannot
  // be adopted across realms (the assignment throws), so a root from another
  // realm (e.g. an iframe) degrades to carets-only rendering instead of
  // crashing.
  private _styleRoot(node: Node): Document | ShadowRoot | null {
    if (node instanceof Document || node instanceof ShadowRoot) {
      return node;
    }
    return null;
  }
}

import {IQuillCursorsResolvedOptions} from './i-quill-cursors-options.js';
import IQuillRange from './i-range.js';
import {ICoordinates} from './i-coordinates.js';
import ICursorHighlight from './i-cursor-highlight.js';
import CursorHighlight from './cursor-highlight.js';
import NoOpCursorHighlight from './no-op-cursor-highlight.js';

export default class Cursor {
  public static readonly CONTAINER_ELEMENT_TAG = 'SPAN';
  public static readonly SELECTION_ELEMENT_TAG = 'SPAN';
  public static readonly CURSOR_CLASS = 'ql-cursor';
  public static readonly SELECTION_CLASS = 'ql-cursor-selections';
  public static readonly SELECTION_BLOCK_CLASS = 'ql-cursor-selection-block';
  public static readonly CARET_CLASS = 'ql-cursor-caret';
  public static readonly CARET_CONTAINER_CLASS = 'ql-cursor-caret-container';
  public static readonly CONTAINER_HOVER_CLASS = 'hover';
  public static readonly CONTAINER_NO_POINTER_CLASS = 'no-pointer';
  public static readonly FLAG_CLASS = 'ql-cursor-flag';
  public static readonly FLAG_FLIPPED_CLASS = 'flag-flipped';
  public static readonly NAME_CLASS = 'ql-cursor-name';
  public static readonly HIDDEN_CLASS = 'hidden';
  public static readonly NO_DELAY_CLASS = 'no-delay';

  public readonly id: string;
  public readonly name: string;
  public readonly color: string;
  public range: IQuillRange | null = null;
  public readonly highlightName: string;

  // Assigned by build(), which runs before any other method is used.
  private _el!: HTMLElement;
  private _selectionEl!: HTMLElement;
  private _caretEl!: HTMLElement;
  private _flagEl!: HTMLElement;
  private _hideDelay!: string;
  private _hideSpeedMs!: number;
  private _positionFlag?: (flag: HTMLElement, caretRectangle: ClientRect, container: ClientRect) => void;
  private readonly _highlight: ICursorHighlight;

  public constructor(id: string, name: string, color: string) {
    this.id = id;
    this.name = name;
    this.color = color;
    this._highlight = CursorHighlight.isSupported() ?
        new CursorHighlight(color) :
        new NoOpCursorHighlight();
    this.highlightName = this._highlight.name;
    this.toggleNearCursor = this.toggleNearCursor.bind(this);
    this._toggleOpenedCursor = this._toggleOpenedCursor.bind(this);
    this._setHoverState = this._setHoverState.bind(this);
  }

  public build(options: IQuillCursorsResolvedOptions): HTMLElement {
    const element = document.createElement(Cursor.CONTAINER_ELEMENT_TAG);
    element.classList.add(Cursor.CURSOR_CLASS);
    element.id = `ql-cursor-${this.id}`;
    element.innerHTML = options.template;
    const selectionElement = element.getElementsByClassName(Cursor.SELECTION_CLASS)[0] as HTMLElement;
    const caretContainerElement = element.getElementsByClassName(Cursor.CARET_CONTAINER_CLASS)[0] as HTMLElement;
    const caretElement = caretContainerElement.getElementsByClassName(Cursor.CARET_CLASS)[0] as HTMLElement;
    const flagElement = element.getElementsByClassName(Cursor.FLAG_CLASS)[0] as HTMLElement;

    flagElement.style.backgroundColor = this.color;
    caretElement.style.backgroundColor = this.color;

    element.getElementsByClassName(Cursor.NAME_CLASS)[0].textContent = this.name;

    this._hideDelay = `${options.hideDelayMs}ms`;
    this._hideSpeedMs = options.hideSpeedMs;
    this._positionFlag = options.positionFlag;
    flagElement.style.transitionDelay = this._hideDelay;
    flagElement.style.transitionDuration = `${this._hideSpeedMs}ms`;

    this._el = element;
    this._selectionEl = selectionElement;
    this._caretEl = caretContainerElement;
    this._flagEl = flagElement;

    caretContainerElement.addEventListener('mouseover', this._setHoverState, {passive: true});

    return this._el;
  }

  public show(): void {
    this._el.classList.remove(Cursor.HIDDEN_CLASS);
    this._highlight.setVisible(true);
  }

  // The highlight lives in the global registry, not in this hidden container,
  // so it is toggled through its stylesheet instead of the hidden class.
  public hide(): void {
    this._el.classList.add(Cursor.HIDDEN_CLASS);
    this._highlight.setVisible(false);
  }

  public remove(): void {
    this._highlight.detach();
    this._el.remove();
  }

  public toggleNearCursor(pointX: number, pointY: number): boolean {
    const {left, right, top, bottom} = this._getCoordinates();

    const isXNear = pointX >= left && pointX <= right;
    const isYNear = pointY >= top && pointY <= bottom;
    const shouldShow = isXNear && isYNear;

    this._caretEl.classList.toggle(Cursor.CONTAINER_HOVER_CLASS, shouldShow);

    return shouldShow;
  }

  public toggleFlag(shouldShow?: boolean): void {
    const isShown = this._caretEl.classList.toggle(Cursor.CONTAINER_HOVER_CLASS, shouldShow);
    if (isShown) return;

    this._flagEl.classList.add(Cursor.NO_DELAY_CLASS);
    // We have to wait for the animation before we can put the delay back
    setTimeout(() => this._flagEl.classList.remove(Cursor.NO_DELAY_CLASS), this._hideSpeedMs);
  }

  public updateCaret(rectangle: ClientRect, container: ClientRect): void {
    this._caretEl.style.top = `${rectangle.top}px`;
    this._caretEl.style.left = `${rectangle.left}px`;
    this._caretEl.style.height = `${rectangle.height}px`;

    if (this._positionFlag) {
      this._positionFlag(this._flagEl, rectangle, container);
    } else {
      this._updateCaretFlag(rectangle, container);
    }
  }

  public setSelectionRange(range: Range | null): void {
    this._highlight.setRange(range, this._el.getRootNode());
  }

  // Custom highlights cannot paint over embeds, so embeds in the selection
  // (inline like images, block like videos) get a tinted overlay instead.
  public updateEmbedSelections(rectangles: ClientRect[], container: ClientRect): void {
    if (!this._selectionEl) return; // custom template without a selections element

    this._selectionEl.innerHTML = '';
    rectangles
      .filter((rectangle: ClientRect) => rectangle.width && rectangle.height)
      .forEach((rectangle: ClientRect) => {
        this._selectionEl.appendChild(this._selectionBlock(rectangle, container));
      });
  }

  private _setHoverState(): void {
    document.addEventListener('mousemove', this._toggleOpenedCursor, {passive: true});
  }

  private _toggleOpenedCursor(e: MouseEvent): void {
    const shouldShow = this.toggleNearCursor(e.clientX, e.clientY);
    this._caretEl.classList.toggle(Cursor.CONTAINER_NO_POINTER_CLASS, shouldShow);
    if (!shouldShow) document.removeEventListener('mousemove', this._toggleOpenedCursor);
  }

  private _getCoordinates(): ICoordinates {
    return this._caretEl.getBoundingClientRect();
  }

  private _selectionBlock(rectangle: ClientRect, container: ClientRect): HTMLElement {
    const element = document.createElement(Cursor.SELECTION_ELEMENT_TAG);

    element.classList.add(Cursor.SELECTION_BLOCK_CLASS);
    element.style.top = `${rectangle.top - container.top}px`;
    element.style.left = `${rectangle.left - container.left}px`;
    element.style.width = `${rectangle.width}px`;
    element.style.height = `${rectangle.height}px`;
    element.style.backgroundColor = this.color;

    return element;
  }

  private _updateCaretFlag(caretRectangle: ClientRect, container: ClientRect): void {
    this._flagEl.style.width = '';
    const flagRect = this._flagEl.getBoundingClientRect();

    this._flagEl.classList.remove(Cursor.FLAG_FLIPPED_CLASS);
    if (caretRectangle.left > container.width - flagRect.width) {
      this._flagEl.classList.add(Cursor.FLAG_FLIPPED_CLASS);
    }
    this._flagEl.style.left = `${caretRectangle.left}px`;
    this._flagEl.style.top = `${caretRectangle.top}px`;
    // Chrome has an issue when doing translate3D with non integer width, this ceil is to overcome it.
    this._flagEl.style.width = `${Math.ceil(flagRect.width)}px`;
  }
}
